INSERT INTO USR_INFO (
                       USR_ID
                     , PASSWD
                     , USR_NM
                     , USR_MBTLNUM
                     , USR_GRP_ID
                     , USE_AT
                     , CREAT_ID
                     , CREAT_DT
                     , UPDT_ID
                     , UPDT_DT
                     , USR_HEALTH1
                     , USR_HEALTH2
                     , USR_HEALTH3
                     , USR_HEALTH4
                     , USR_HEALTH5
                     , USR_HEALTH6
                     , USR_HEALTH7
                     , USR_HEALTH8
) VALUES (
           #{userId}
         , #{passwd}
         , #{userName}
         , #{mobileNumber}
         , #{userGroupId}
         , #{useAT}
         , #{createId}
         , NOW()
         , #{updateId}
         , NOW()
         , #{userHealth1}
         , #{userHealth2}
         , #{userHealth3}
         , #{userHealth4}
         , #{userHealth5}
         , #{userHealth6}
         , #{userHealth7}
         , #{userHealth8}
         )
